1|/**
2| * @file Living Fleet pet commands (barecode). Read-only creature views.
3| * Fetches from the orchestrator fleet API; never touches the panel DB.
4| */
5|
6|const { EmbedBuilder } = require('discord.js');
7|
8|const COMMAND_SPECS = [
9|  { name: 'pet', description: 'Living Fleet creature commands', options: [{ name: 'list', description: 'List all creatures with mood and stage', type: 1 }] },
10|  { name: 'pet-status', description: 'Show one creature with vitals', options: [{ name: 'workload', description: 'Workload ID of the creature', type: 3, required: true }] },
11|];
12|
13|const MOOD_EMOJI = {
14|  thriving: '🌟', content: '😊', sleepy: '😴', hungry: '🍽️',
15|  sick: '🤒', stressed: '😰', sad: '😢', ghost: '👻',
16|};
17|
18|function fleetBase() {
19|  return (process.env.ORCHESTRATOR_URL || 'http://orchestrator-agent:8500').replace(/\/$/, '');
20|}
21|
22|async function fetchJson(path) {
23|  const headers = {};
24|  if (process.env.FEDERATION_API_TOKEN) {
25|    headers.Authorization = `Bearer ${process.env.FEDERATION_API_TOKEN}`;
26|  }
27|  const res = await fetch(`${fleetBase()}${path}`, { headers, signal: AbortSignal.timeout(8000) });
28|  if (!res.ok) throw new Error(`fleet API ${res.status}`);
29|  return res.json();
30|}
31|
32|// Discord embed descriptions cap at 4096 chars; split long fleets across pages.
33|function paginateLines(lines, limit = 4000) {
34|  const pages = [];
35|  let current = '';
36|  for (const line of lines) {
37|    if ((current + line + '\n').length > limit && current) {
38|      pages.push(current);
39|      current = '';
40|    }
41|    current += `${line}\n`;
42|  }
43|  if (current) pages.push(current);
44|  return pages.length ? pages : ['No creatures yet.'];
45|}
46|
47|function toSpec() {
48|  return COMMAND_SPECS;
49|}
50|
51|function isParsed(name) {
52|  return COMMAND_SPECS.some((c) => c.name === name);
53|}
54|
55|async function handle(interaction) {
56|  await interaction.deferReply({ ephemeral: true });
57|  try {
58|    if (interaction.commandName === 'pet') {
59|      const creatures = await fetchJson('/api/v1/fleet/creatures');
60|      if (!creatures.length) return interaction.editReply({ content: 'No creatures yet. They are born when a workload is first seen healthy.' });
61|      const entries = creatures.map((c) => `${MOOD_EMOJI[c.mood] || '❓'} **${c.display_name}** \`(${c.workload_id})\` — ${c.mood} (${c.stage})`);
62|      const pages = paginateLines(entries);
63|      await interaction.editReply({ embeds: [new EmbedBuilder().setTitle('Living Fleet').setDescription(pages[0]).setColor('#7c3aed')] });
64|      for (const page of pages.slice(1)) {
65|        await interaction.followUp({ embeds: [new EmbedBuilder().setTitle('Living Fleet (cont.)').setDescription(page).setColor('#7c3aed')], ephemeral: true });
66|      }
67|      return null;
68|    }
69|    if (interaction.commandName === 'pet-status') {
70|      const workload = interaction.options.getString('workload', true);
71|      const c = await fetchJson(`/api/v1/fleet/creatures/${encodeURIComponent(workload)}`);
72|      const vitals = Object.entries(c.vitals || {}).map(([k, v]) => `${k}: ${v === null ? 'unknown' : v}`).join('\n');
73|      const embed = new EmbedBuilder()
74|        .setTitle(`${MOOD_EMOJI[c.mood] || '❓'} ${c.display_name}`)
75|        .setDescription(`Mood: **${c.mood}**\nStage: ${c.stage}\n\n${vitals}`)
76|        .setColor('#7c3aed');
77|      return interaction.editReply({ embeds: [embed] });
78|    }
79|  } catch (error) {
80|    console.error('[PetCommands] failed:', error.message);
81|    return interaction.editReply({ content: 'The fleet is unreachable right now (orchestrator down or feature disabled).' });
82|  }
83|}
84|
85|module.exports = { toSpec, isParsed, handle };

