1|const fs = require('fs');
2|const path = require('path');
3|const { query, getDbPool } = require('./db');
4|
5|// Fallback path must be writable under read_only:true (see docker-compose.yml tmpfs: /tmp)
6|const SERVER_LIMITS_FILE = path.join('/tmp', 'server_limits.json');
7|// Legacy path for migration / inspection only
8|const LEGACY_LIMITS_FILE = path.join(__dirname, '..', 'server_limits.json');
9|
10|let _ensureTablePromise = null;
11|
12|async function _ensureTable() {
13|  if (!_ensureTablePromise) {
14|    _ensureTablePromise = query(`
15|      CREATE TABLE IF NOT EXISTS server_limits (
16|        user_id VARCHAR(255) NOT NULL,
17|        server_identifier VARCHAR(255) NOT NULL,
18|        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
19|        PRIMARY KEY (user_id, server_identifier)
20|      )
21|    `);
22|  }
23|  return _ensureTablePromise;
24|}
25|
26|async function loadServerLimits() {
27|  try {
28|    await _ensureTable();
29|    const result = await query(
30|      'SELECT user_id, server_identifier FROM server_limits'
31|    );
32|    const limits = {};
33|    for (const row of result.rows) {
34|      if (!limits[row.user_id]) limits[row.user_id] = [];
35|      limits[row.user_id].push(row.server_identifier);
36|    }
37|    return limits;
38|  } catch (error) {
39|    console.error('[ServerLimits] DB load failed, trying JSON fallback:', error.message);
40|  }
41|  // Try new writable location first, then legacy for migration
42|  for (const candidate of [SERVER_LIMITS_FILE, LEGACY_LIMITS_FILE]) {
43|    try {
44|      if (fs.existsSync(candidate)) {
45|        return JSON.parse(fs.readFileSync(candidate, 'utf8'));
46|      }
47|    } catch (error) {
48|      console.error(`[ServerLimits] JSON fallback read failed (${candidate}):`, error.message);
49|    }
50|  }
51|  try {
52|    fs.writeFileSync(SERVER_LIMITS_FILE, JSON.stringify({}));
53|    return {};
54|  } catch (error) {
55|    console.error('[ServerLimits] JSON fallback init failed (read_only?):', error.message);
56|    // Preserve failure signal – caller can decide to fail server creation
57|    return {};
58|  }
59|}
60|
61|async function saveServerLimits(userId, serverIdentifier) {
62|  try {
63|    await _ensureTable();
64|    await query(
65|      'INSERT INTO server_limits (user_id, server_identifier) VALUES ($1, $2) ON CONFLICT DO NOTHING',
66|      [userId, serverIdentifier]
67|    );
68|    return true;
69|  } catch (error) {
70|    console.error('[ServerLimits] DB save failed, using JSON fallback:', error.message);
71|    try {
72|      let limits = {};
73|      if (fs.existsSync(SERVER_LIMITS_FILE)) {
74|        limits = JSON.parse(fs.readFileSync(SERVER_LIMITS_FILE, 'utf8'));
75|      } else if (fs.existsSync(LEGACY_LIMITS_FILE)) {
76|        limits = JSON.parse(fs.readFileSync(LEGACY_LIMITS_FILE, 'utf8'));
77|      }
78|      if (!limits[userId]) limits[userId] = [];
79|      if (limits[userId].includes(serverIdentifier)) return true;
80|      limits[userId].push(serverIdentifier);
81|      fs.writeFileSync(SERVER_LIMITS_FILE, JSON.stringify(limits, null, 2));
82|      return true;
83|    } catch (fsError) {
84|      console.error('[ServerLimits] JSON fallback save failed (read_only? persistent volume needed):', fsError.message);
85|      // Explicit failure – callers should treat this as persistence error
86|      return false;
87|    }
88|  }
89|}
90|
91|module.exports = { loadServerLimits, saveServerLimits };

