158|    /**
159|     * Show a one-shot status embed.
160|     * @param {import('discord.js').CommandInteraction} interaction
161|     * @returns {Promise<void>}
162|     */
163|    async showStatus(interaction) {
164|        await interaction.deferReply();
165|        const embed = await this.createStatusEmbed();
166|        await interaction.editReply({ embeds: [embed] });
167|    }
168|
169|    /**
170|     * Handle the refresh button interaction.
171|     * @param {import('discord.js').ButtonInteraction} interaction
172|     * @returns {Promise<void>}
173|     */
174|    async handleButton(interaction) {
175|        if (interaction.customId !== 'refresh_status') return;
176|        await interaction.deferUpdate();
