180|    /**
181|     * Format bytes into a human-readable string.
182|     * @param {number} bytes
183|     * @returns {string}
184|     */
185|    formatBytes(bytes) {
186|        if (bytes === 0) return '0 B';
187|        const i = parseInt(Math.floor(Math.log(bytes) / Math.log(1024)), 10);
188|        return (bytes / Math.pow(1024, i)).toFixed(1) + ' ' + BYTE_UNITS[i];
