193|     * @param {number} seconds
194|     * @returns {string}
195|     */
196|    formatUptime(seconds) {
197|        const d = Math.floor(seconds / 86400);
198|        const h = Math.floor((seconds % 86400) / 3600);
199|        const m = Math.floor((seconds % 3600) / 60);
200|        const parts = [];
201|        if (d > 0) parts.push(`${d}d`);
202|        if (h > 0) parts.push(`${h}h`);
203|        parts.push(`${m}m`);
204|        return parts.join(' ');
205|    }
