1|/**
2| * @file CLI Bridge for Discord Bot
3| * Replaces direct Pterodactyl API calls with `ipilot` CLI subprocess calls.
4| * @example
5| *   const { cli } = require('./cli-bridge');
6| *   const result = cli('server list');
7| *   if (result.success) {
8| *     const servers = result.data;
9| *   }
10| */
11|
12|const { execSync } = require('child_process');
13|
14|/** @constant {string} */
15|const IPILOT_CMD = process.env.IPILOT_CMD || 'ipilot';
16|/** @constant {number} */
17|const CLI_TIMEOUT_MS = 30000;
18|
19|/**
20| * @typedef {Object} CliResult
21| * @property {boolean} success - Whether the command succeeded
22| * @property {*} data - Parsed JSON result data
23| * @property {string} [error] - Error message if failed
24| */
25|
26|/**
27| * Execute an ipilot CLI command and return parsed JSON.
28| * @param {string} command - The ipilot subcommand to run (e.g. 'server list')
29| * @returns {CliResult} The result object with success flag and parsed data
30| * @throws {Error} If the command string is invalid
31| */
32|// Bridge the two interfaces without letting their assumptions mingle unsupervised.
33|function cli(command) {
34|  if (!command || typeof command !== 'string') {
35|    return { success: false, data: null, error: 'Command must be a non-empty string' };
36|  }
37|
38|  try {
39|    const fullCmd = `${IPILOT_CMD} ${command} --output json`;
40|    const stdout = execSync(fullCmd, {
