13|
14|class ServerStatus {
15|    /**
16|     * @param {import('discord.js').Client} client
17|     */
18|    constructor(client) {
19|        this.client = client;
20|        /** @type {Map<string, Object>} */
21|        this.widgets = new Map();
22|        /** @type {Map<string, NodeJS.Timeout>} */
23|        this.updateIntervals = new Map();
24|    }
25|
26|    /**
27|     * Initialize all registered status widgets.
28|     * @param {import('discord.js').Client} client
29|     * @returns {void}
30|     */
31|    initialize(client) {
32|        for (const [channelId] of this.widgets) {
33|            this.startWidgetUpdate(channelId);
34|        }
35|    }
36|
37|    /**
38|     * Route a /status subcommand interaction.
39|     * @param {import('discord.js').CommandInteraction} interaction
40|     * @returns {Promise<void>}
41|     */
42|    async handleCommand(interaction) {
43|        if (interaction.commandName !== 'status') return;
44|
45|        const sub = interaction.options.getSubcommand();
46|        if (sub === 'widget') {
47|            await this.createWidget(interaction);
48|        } else if (sub === 'info') {
49|            await this.showStatus(interaction);
50|        }
51|    }
52|
53|    /**
54|     * Create a live status widget in the current channel.
55|     * @param {import('discord.js').CommandInteraction} interaction
56|     * @returns {Promise<void>}
57|     */
58|    async createWidget(interaction) {
59|        if (!interaction.member.permissions.has('ADMINISTRATOR')) {
60|            return interaction.reply({ content: '❌ Du benötigst Administrator-Rechte.', ephemeral: true });
61|        }
62|
63|        await interaction.deferReply();
64|
65|        const embed = await this.createStatusEmbed();
66|        const row = new ActionRowBuilder().addComponents(
67|            new ButtonBuilder()
68|                .setCustomId('refresh_status')
69|                .setLabel('Refresh')
70|                .setStyle(ButtonStyle.Primary)
71|                .setEmoji('🔄')
72|        );
73|
74|        const msg = await interaction.channel.send({ embeds: [embed], components: [row] });
75|        this.widgets.set(interaction.channelId, { messageId: msg.id, channelId: interaction.channelId });
76|        this.startWidgetUpdate(interaction.channelId);
77|
78|        await interaction.editReply({ content: '✅ Status-Widget erstellt!', ephemeral: true });
79|    }
80|
81|    /**
82|     * Start the periodic update interval for a widget.
83|     * @param {string} channelId
84|     * @returns {void}
85|     */
86|    startWidgetUpdate(channelId) {
87|        if (this.updateIntervals.has(channelId)) {
88|            clearInterval(this.updateIntervals.get(channelId));
89|        }
90|        const interval = setInterval(() => this.updateWidget(channelId), WIDGET_UPDATE_INTERVAL_MS);
