69|    GB: 1024 ** 3, GiB: 1024 ** 3,
70|    TB: 1024 ** 4, TiB: 1024 ** 4,
71|    PB: 1024 ** 5, PiB: 1024 ** 5,
72|  };
73|  return Math.round(parseFloat(match[1]) * (units[match[2]] || 1));
