1|<# .SYNOPSIS
2|Build Docker images for all Infra Pilot services on Windows.
3|.PARAMETER Push
4|Push images to registry after build
5|.PARAMETER Registry
6|Container registry URL (default: REGISTRY env var)
7|#>
8|param([switch]$Push, [string]$Registry = "")
9|
10|$ErrorActionPreference = "Stop"
11|$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
12|$RootDir = Split-Path -Parent $ScriptDir
13|
14|function Info    { Write-Host "[INFO] $($args[0])" -ForegroundColor Blue }
15|function Success { Write-Host "[OK]   $($args[0])" -ForegroundColor Green }
16|function Warn    { Write-Host "[WARN] $($args[0])" -ForegroundColor Yellow }
17|function Error   { Write-Host "[ERR]  $($args[0])" -ForegroundColor Red }
18|
19|if (!(Get-Command docker -ErrorAction SilentlyContinue)) { Error "Docker is not installed"; exit 1 }
20|Success "Docker found: $(docker --version 2>&1)"
21|
22|$version = if (git describe --tags --always 2>$null) { git describe --tags --always } else { "latest" }
23|if (!$Registry) { $Registry = $env:REGISTRY }
24|Info "Using version tag: $version"
25|
26|$Services = @(
27|    "services/orchestrator-agent",
28|    "services/discord-service",
29|    "services/management-panel"
30|)
31|$buildFailed = 0
32|
33|foreach ($service in $Services) {
34|    $servicePath = Join-Path $RootDir $service
35|    if (!(Test-Path $servicePath)) { Warn "Service directory not found: $service"; continue }
36|
37|    $name = Split-Path $service -Leaf
38|    $df = Join-Path $servicePath "Dockerfile"
39|    if (!(Test-Path $df)) { Warn "Dockerfile not found for $name, skipping"; continue }
40|
41|    $imageName = "infra-pilot-$name"
42|    $imageTag = $version
43|    if ($Registry) { $imageName = "$Registry/$imageName" }
44|
45|    Info "Building $name..."
46|    docker build -f $df -t "${imageName}:${imageTag}" -t "${imageName}:latest" $servicePath
47|    if ($LASTEXITCODE -eq 0) {
48|        Success "$name built successfully"
49|        if ($Push -and $Registry) {
50|            Info "Pushing ${imageName}:${imageTag}..."
51|            docker push "${imageName}:${imageTag}"
52|            docker push "${imageName}:latest"
53|        } elseif ($Push) { Warn "No registry specified, skipping push" }
54|    } else { Error "Failed to build $name"; $buildFailed++ }
55|}
56|
57|if ($buildFailed -eq 0) { Success "All builds completed successfully!"; exit 0 }
58|else { Error "$buildFailed build(s) failed"; exit 1 }

