1|<# .SYNOPSIS
2|Run verification stages across the Infra Pilot project on Windows.
3|.PARAMETER Offline
4|Skip network-dependent checks
5|.PARAMETER Json
6|Output results as JSON
7|.PARAMETER Stages
8|Comma-separated list of stages (default: health,setup,test,lint,integration)
9|#>
10|param([switch]$Offline, [switch]$Json, [string]$Stages = "health,setup,test,lint,integration")
11|
12|$ErrorActionPreference = "Stop"
13|$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
14|$RootDir = Split-Path -Parent $ScriptDir
15|
16|function Info    { Write-Host "[INFO] $($args[0])" -ForegroundColor Blue }
17|function Success { Write-Host "[OK]   $($args[0])" -ForegroundColor Green }
18|function Error   { Write-Host "[ERR]  $($args[0])" -ForegroundColor Red }
19|
20|$stageList = $Stages.Split(',', [StringSplitOptions]::RemoveEmptyEntries)
21|$Failed = 0
22|$stageJson = @()
23|
24|foreach ($stage in $stageList) {
25|    Info "Stage: $stage"
26|    $status = "passed"
27|    switch ($stage) {
28|        "health" {
29|            $cmd = Join-Path $RootDir "scripts\healthcheck.ps1"
30|            & $cmd; if ($LASTEXITCODE -ne 0) { $status = "failed"; $Failed++ }
31|        }
32|        "setup" {
33|            $cmd = Join-Path $RootDir "scripts\setup.ps1"
34|            $args = @(); if ($Offline) { $args += "-Offline" }
35|            & $cmd @args; if ($LASTEXITCODE -ne 0) { $status = "failed"; $Failed++ }
36|        }
37|        "test" {
38|            $cmd = Join-Path $RootDir "scripts\test.ps1"
39|            $args = @(); if ($Offline) { $args += "-Offline" }
40|            & $cmd @args; if ($LASTEXITCODE -ne 0) { $status = "failed"; $Failed++ }
41|        }
42|        default { Error "Unknown stage '$stage'"; $status = "failed"; $Failed++ }
43|    }
44|    if ($status -eq "passed") { Success "Stage succeeded: $stage" }
45|    else { Error "Stage failed: $stage" }
46|    $stageJson += @{stage = $stage; status = $status}
47|}
48|
49|if ($Json) {
50|    $jsonStr = $stageJson | ConvertTo-Json -Compress
