11|
12|$ErrorActionPreference = "Stop"
13|$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
14|$RootDir = Split-Path -Parent $ScriptDir
15|
16|function Info    { Write-Host "[INFO] $($args[0])" -ForegroundColor Blue }
17|function Success { Write-Host "[OK]   $($args[0])" -ForegroundColor Green }
18|function Error   { Write-Host "[ERR]  $($args[0])" -ForegroundColor Red }
19|
20|$stageList = $Stages.Split(',', [StringSplitOptions]::RemoveEmptyEntries)
21|$Failed = 0
22|$stageJson = @()
23|
24|foreach ($stage in $stageList) {
25|    Info "Stage: $stage"
26|    $status = "passed"
27|    switch ($stage) {
28|        "health" {
29|            $cmd = Join-Path $RootDir "scripts\healthcheck.ps1"
30|            & $cmd; if ($LASTEXITCODE -ne 0) { $status = "failed"; $Failed++ }
