1|<# .SYNOPSIS
2|Set up the Infra Pilot development environment on Windows.
3|.DESCRIPTION
4|Checks prerequisites, validates infrastructure files, and creates .env from .env.example.
5|.PARAMETER Offline
6|Skip package downloads (use cached artifacts only)
7|#>
8|param([switch]$Offline)
9|
10|$ErrorActionPreference = "Stop"
11|$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
12|$RootDir = Split-Path -Parent $ScriptDir
13|
14|function Info  { Write-Host "[INFO] $($args[0])" -ForegroundColor Blue }
15|function Success { Write-Host "[OK]   $($args[0])" -ForegroundColor Green }
16|function Warn  { Write-Host "[WARN] $($args[0])" -ForegroundColor Yellow }
17|function Error { Write-Host "[ERR]  $($args[0])" -ForegroundColor Red }
18|
19|function CheckCommand($cmd, $name) {
20|    if (!(Get-Command $cmd -ErrorAction SilentlyContinue)) {
21|        Warn "$name is not installed"
22|        return $false
23|    }
24|    return $true
25|}
26|
27|$Services = @(
28|    "services/orchestrator-agent",
29|    "services/discord-service",
30|    "services/management-panel"
31|)
32|
33|Info "Checking prerequisites..."
34|if ($Offline) { Info "Offline mode enabled: package installation steps skipped" }
35|
36|$MissingDeps = 0
37|if (!(CheckCommand git "Git")) { $MissingDeps = 1 }
38|if (!(CheckCommand docker "Docker")) { Warn "Docker not found - using local setup" }
39|if (!(CheckCommand python "Python 3")) { Warn "Python 3 not found - skipping orchestrator-agent setup" }
40|if (!(CheckCommand node "Node.js")) { Warn "Node.js not found - skipping Node.js services setup" }
41|if (!(CheckCommand npm "npm")) { Warn "npm not found - skipping Node.js services setup" }
42|
43|if ($MissingDeps -eq 1) { Error "Missing critical dependencies"; exit 1 }
44|Success "Prerequisites check passed"
45|
46|Info "Validating infrastructure files..."
47|$InfraFiles = @(
48|    "docker-compose.yml",
49|    ".env.example",
50|    "infra/monitoring/prometheus/prometheus.yml",
51|    "infra/monitoring/grafana/provisioning/datasources/prometheus.yml"
52|)
53|foreach ($file in $InfraFiles) {
54|    $path = Join-Path $RootDir $file
55|    if (Test-Path $path) { Success "Found $file" }
56|    else { Warn "Missing $file - some features may not work" }
57|}
58|
