60|    $path = Join-Path $RootDir $service
61|    if (!(Test-Path $path)) { Warn "Service directory not found: $service"; continue }
62|    $name = Split-Path $service -Leaf
63|    $df = Join-Path $path "Dockerfile"
64|    $di = Join-Path $path ".dockerignore"
65|    if ((Test-Path $df) -and (Test-Path $di)) { Info "$name is Docker-ready" }
66|}
67|
68|$envExample = Join-Path $RootDir ".env.example"
69|$envFile = Join-Path $RootDir ".env"
70|if ((Test-Path $envExample) -and !(Test-Path $envFile)) {
71|    Copy-Item $envExample $envFile
72|    Warn "Created .env from .env.example - please configure with your settings"
73|} elseif (Test-Path $envFile) { Success ".env already exists" }
74|else { Warn "No .env.example found - you may need to create .env manually" }
75|
76|Success "Setup complete!"
77|Info "Next steps:"
