1|// Shared helpers for the Infra Pilot load test scenarios.
2|//
3|// Environment variables (all optional except where noted):
4|//   K6_TARGET_ORCHESTRATOR  Base URL of the orchestrator agent.
5|//                           Default: http://localhost:8500
6|//   K6_TARGET_PANEL         Base URL of the management panel backend.
7|//                           Set to an empty value to disable panel checks
8|//                           (used in CI where only the orchestrator runs).
9|//   K6_FEDERATION_TOKEN     Bearer [REDACTED] for /api/ routes. When set on the
10|//                           server the orchestrator fails closed, so the
11|//                           client token must match it.
12|//   K6_GITOPS_WEBHOOK_TOKEN HMAC-SHA256 key used to sign /webhook/gitops
13|//                           POSTs. Must match GITOPS_WEBHOOK_TOKEN of the
14|//                           orchestrator.
15|//   K6_MANIFEST_COUNT       Instances per deployment manifest (default 1).
16|//
17|// Every request carries the tag `type`, which the scenario files use to
18|// define per-endpoint thresholds, e.g. http_req_duration{type:deployments}.
19|import http from 'k6/http';
20|import { check } from 'k6';
21|import crypto from 'k6/crypto';
22|
23|export const TARGET_ORCHESTRATOR =
24|  __ENV.K6_TARGET_ORCHESTRATOR || 'http://localhost:8500';
25|// The panel checks are disabled when the variable is unset OR empty
26|// (in CI only the orchestrator runs, so "" must not fall back to a URL).
27|const panelTarget = __ENV.K6_TARGET_PANEL;
28|export const TARGET_PANEL =
29|  panelTarget === undefined || panelTarget === '' ? '' : panelTarget;
30|
31|const FEDERATION_TOKEN = __ENV.K6_FEDERATION_TOKEN || '';
32|const GITOPS_TOKEN = __ENV.K6_GITOPS_WEBHOOK_TOKEN || '';
33|
34|export function federationHeaders() {
35|  const headers = { 'Content-Type': 'application/json' };
36|  if (FEDERATION_TOKEN) {
37|    headers.Authorization = `Bearer ${FEDERATION_TOKEN}`;
38|  }
39|  return headers;
40|}
41|
42|function hmacSha256Hex(secret, message) {
43|  const hasher = crypto.createHMAC('sha256', secret);
44|  hasher.update(message);
45|  return hasher.digest('hex');
46|}
47|
48|// Signs the exact string that is sent over the wire. The orchestrator
49|// expects X-Timestamp within its replay window and X-Signature-256 =
50|// sha256=<HMAC-SHA256(GITOPS_WEBHOOK_TOKEN, "<X-Timestamp>\n<body")>.
51|export function gitopsHeaders(bodyString) {
52|  const timestamp = String(Math.floor(Date.now() / 1000));
53|  const signature = 'sha256=' + hmacSha256Hex(GITOPS_TOKEN, `${timestamp}\n${bodyString}`);
54|  return {
